function withFileLock(lockFile,operation){
  const owner=`${process.pid}:${crypto.randomBytes(16).toString('hex')}`,deadline=Date.now()+2500;
  let acquired=false;
  while(!acquired){
    try{const fd=fs.openSync(lockFile,'wx',0o600);try{fs.writeFileSync(fd,owner);fs.fsyncSync(fd)}finally{fs.closeSync(fd)}acquired=true}
    catch(e){
      if(e.code!=='EEXIST')throw e;
      try{if(Date.now()-fs.statSync(lockFile).mtimeMs>30000)fs.unlinkSync(lockFile)}catch(lockError){if(lockError.code!=='ENOENT')throw lockError}
      if(Date.now()>=deadline)throw new Error('Persistente datastore is tijdelijk vergrendeld');
      Atomics.wait(fileLockWaitArray,0,0,25);
    }
  }
  try{return operation()}finally{try{if(fs.readFileSync(lockFile,'utf8')===owner)fs.unlinkSync(lockFile)}catch(e){if(e.code!=='ENOENT')console.error('[DATASTORE LOCK RELEASE ERROR]',redactJarvisText(e.message,160))}}
}
