  const unique=[...new Map(sources.filter(x=>{try{return ['http:','https:'].includes(new URL(x?.url).protocol)}catch{return false}}).map(x=>[x.url,{type:x.type||'url',url:x.url,title:redactJarvisText(x.title||x.url,500)}])).values()];
