function body(req){ return new Promise((resolve,reject)=>{ let s=''; req.on('data',c=>{s+=c;if(s.length>5e6){reject(new Error('Payload te groot'));req.destroy();}}); req.on('end',()=>{try{resolve(s?JSON.parse(s):{})}catch{reject(new Error('Ongeldige JSON'));}}); req.on('error',reject); }); }
function rawBody(req){return new Promise((resolve,reject)=>{const chunks=[];let n=0;req.on('data',c=>{n+=c.length;if(n>5e6){reject(new Error('Payload te groot'));req.destroy();return}chunks.push(c)});req.on('end',()=>resolve(Buffer.concat(chunks)));req.on('error',reject)})}
