function moduleFor(message=''){
  const q=message.toLowerCase();
  const rules=[['inkoop',['inkoop','inkopen','kopen','deal','aanbieder','import']],['verkoop',['verkoop','verkopen','prijs','listing']],['crm',['klant','lead','crm','pipeline']],['agenda',['agenda','afspraak','proefrit','terugbellen']],['voorraad',['voorraad','statijd','voorraadwaarde']],['social_media',['instagram','facebook','tiktok','social']],['google_ads',['google ads','zoekwoord','cpc','roas']],['automatisering',['workflow','automatis','trigger']],['communicatie',['mail','whatsapp','bel','telefon','bericht']],['rapportages',['rapport','kpi','forecast']],['integraties',['integratie','connector','api']],['data',['data','rdw','bpm','vin','marktprijs']]];
  const hits=rules.filter(([,w])=>w.some(x=>q.includes(x))).map(([m])=>m); return hits.length?hits:['data'];
}
function deterministic(mod,message,c){
  const r=arr(records,key(c,mod));
  if(mod==='inkoop'){
    const cars=r.filter(x=>x&&typeof x==='object');
    if(!cars.length) return 'Inkoop Engine is actief. Er staat nog geen echte voertuigdata in de Inkoop-database. Voeg connector- of ingestdata toe; ik verzin geen voertuigen, prijzen of marges.';
    const ranked=cars.map(x=>{const buy=Number(x.purchase_price||x.price||0),sale=Number(x.expected_sale_price||x.market_price||0),cost=Number(x.bpm||0)+Number(x.transport||0)+Number(x.other_costs||0);return {...x,_margin:sale&&buy?sale-buy-cost:null,_score:Number(x.score||0)};}).sort((a,b)=>(b._score||b._margin||0)-(a._score||a._margin||0)).slice(0,5);
    return `Top ${ranked.length} inkoopkansen op basis van aanwezige data:\n`+ranked.map((x,i)=>`${i+1}. ${x.make||x.brand||''} ${x.model||''} | inkoop ${x.purchase_price||x.price||'onbekend'} | marge ${x._margin??'onbekend'} | score ${x._score||'n.v.t.'}`).join('\n');
  }
  if(mod==='voorraad' || mod==='verkoop'){
    const stock=arr(records,key(c,'voorraad'));
    return stock.length?`${MODULES[mod]} Engine actief. ${stock.length} voorraadrecords beschikbaar voor analyse.`:`${MODULES[mod]} Engine is actief. Er is nog geen voorraaddata ingeladen; ik verzin geen voorraad.`;
  }
  if(mod==='crm') return `CRM Engine actief. ${crmTotalCount(c)+arr(records,key(c,'crm')).length} CRM-records beschikbaar.`;
  if(mod==='agenda') return `Agenda Engine actief. ${arr(records,key(c,'agenda')).length} agenda-records beschikbaar.`;
  return `${MODULES[mod]} Engine is actief. Vraag ontvangen: “${message}”. Voor inhoudelijke conclusies gebruik ik alleen werkelijk ingeladen data of geconfigureerde externe AI.`;
}
async function openaiText(system,input){
  const apiKey=cleanEnv('FOUNDLY_AI_API_KEY')||cleanEnv('OPENAI_API_KEY');if(!apiKey)return '';
  const base=cleanEnv('FOUNDLY_AI_BASE_URL','https://api.openai.com/v1').replace(/\/$/,'');const model=cleanEnv('FOUNDLY_AI_MODEL','gpt-5.6');
  try{const r=await fetch(`${base}/responses`,{method:'POST',headers:{'content-type':'application/json','authorization':`Bearer ${apiKey}`},body:JSON.stringify({model,instructions:system,input}),signal:timeoutSignal()});const j=await r.json();if(r.ok)return j.output_text||((j.output||[]).flatMap(x=>x.content||[]).find(x=>x.type==='output_text')||{}).text||'';console.error('[AI RESPONSES ERROR]',r.status,redactJarvisText(j.error?.message||'unknown'))}catch(e){console.error('[AI RESPONSES ERROR]',redactJarvisText(e.message))}
  try{const r=await fetch(`${base}/chat/completions`,{method:'POST',headers:{'content-type':'application/json','authorization':`Bearer ${apiKey}`},body:JSON.stringify({model,messages:[{role:'system',content:system},{role:'user',content:input}]}),signal:timeoutSignal()});const j=await r.json();if(r.ok)return j.choices?.[0]?.message?.content||'';console.error('[AI CHAT FALLBACK ERROR]',r.status,redactJarvisText(j.error?.message||'unknown'))}catch(e){console.error('[AI CHAT FALLBACK ERROR]',redactJarvisText(e.message))}
  return '';
}
function contextFor(c,mods,limit=60){
  const rows=[];
  for(const mod of mods){
    if(!moduleVisible(mod,COMPOSITION,c,platformPrincipal()))continue;
    for(const x of scopedRecordRows(c,mod).slice(-limit))rows.push({module:mod,...x});
    if(mod==='crm')for(const entity of ['leads','contacts','companies','deals','opportunities','tasks','appointments','activities'])for(const x of crmOwnedRows(c,entity).slice(-limit))rows.push({module:'crm',crm_entity:entity,...x});
  }
  return rows.slice(-limit*4);
}
