const jarvisInflight=new Map();
function jarvisTurn(message,c,options={}){const conversationId=normalizeConversationId(options.conversation_id),turnId=normalizeTurnId(options.turn_id),inflightKey=`${key(c,'jarvis-turn')}:${conversationId}:${turnId}`;if(jarvisInflight.has(inflightKey))return jarvisInflight.get(inflightKey);const run=runJarvisTurn(message,c,{...options,conversation_id:conversationId,turn_id:turnId}).finally(()=>jarvisInflight.delete(inflightKey));jarvisInflight.set(inflightKey,run);return run}
