    const inventoryMatches=u.pathname.match(/^\/api\/crm\/inventory\/([A-Za-z0-9_.:-]{1,200})\/customer-matches$/);if(inventoryMatches&&req.method==='GET'){json(res,200,{ok:true,matches:CRM_CORE.inventoryCustomerMatches(c,principal,inventoryMatches[1],{limit:u.searchParams.get('limit')||20})});return true}
