    const move=u.pathname.match(/^\/api\/crm\/deals\/([A-Za-z0-9_.:-]{1,200})\/stage$/);if(move&&['POST','PUT','PATCH'].includes(req.method)){const payload=await body(req);if(!payload.stage_id)throw Object.assign(new Error('stage_id is verplicht'),{statusCode:400,code:'crm_validation_failed'});const deal=CRM_CORE.moveDeal(c,principal,move[1],payload.stage_id,{...crmRequestOptions(req),eventId:String(req.headers['x-foundly-event-id']||id())});json(res,200,{ok:true,deal});return true}
    if(u.pathname==='/api/crm/automation-events'&&req.method==='POST'){const payload=await body(req),result=CRM_CORE.evaluateAutomations(c,principal,payload);json(res,202,{ok:true,...result});return true}
    const exportMatch=u.pathname.match(/^\/api\/crm\/export\/([a-z_]+)$/);if(exportMatch&&req.method==='GET'){json(res,200,CRM_CORE.export(c,principal,exportMatch[1]));return true}
